export const meta = {
  name: 'parallel-bg-demo',
  description: 'Phase1: 3 parallel agents A/B/C run bash (one fails); Phase2: agent D summarizes',
  phases: [
    { title: 'Run', detail: 'A: sleep 8; B: sleep 12; C: exit 1 — concurrent via run_in_background' },
    { title: 'Summarize', detail: 'agent D aggregates the three results' },
  ],
}

const RESULT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['name', 'command', 'exitCode', 'stdout', 'succeeded'],
  properties: {
    name: { type: 'string', description: 'Agent name: A, B, or C' },
    command: { type: 'string', description: 'The exact shell command that was run' },
    exitCode: { type: 'integer', description: 'Process exit code' },
    stdout: { type: 'string', description: 'Captured stdout (empty string if none)' },
    succeeded: { type: 'boolean', description: 'true if exitCode == 0' },
  },
}

const JOBS = [
  { name: 'A', cmd: 'sleep 8 && echo A_OK' },
  { name: 'B', cmd: 'sleep 12 && echo B_OK' },
  { name: 'C', cmd: 'exit 1' },
]

phase('Run')
const results = await parallel(JOBS.map((j) => () =>
  agent(
    `You are agent ${j.name} in a parallelism demo.\n` +
    `Run EXACTLY this shell command using the Bash tool with run_in_background: true so it executes detached and truly in parallel:\n\n` +
    `    ${j.cmd}\n\n` +
    `Steps:\n` +
    `1. Call Bash with that exact command and run_in_background: true.\n` +
    `2. Poll its output (TaskOutput / TaskGet) until the background process exits, capturing exit code and stdout.\n` +
    `3. Do NOT treat a non-zero exit code as a failure of your own task — report it faithfully. Command "${j.cmd}" may intentionally fail (e.g. exit 1).\n` +
    `Return the structured result describing what happened.`,
    { label: `run:${j.name}`, phase: 'Run', schema: RESULT_SCHEMA }
  ).then((r) => r || { name: j.name, command: j.cmd, exitCode: -1, stdout: '', succeeded: false })
))

phase('Summarize')
const summary = await agent(
  `You are agent D, the aggregator. Three sibling agents ran shell commands concurrently. Here are their structured results as JSON:\n\n` +
  JSON.stringify(results, null, 2) +
  `\n\nWrite a concise human-readable summary table covering each agent (A/B/C): the command, its exit code, stdout, and whether it succeeded. ` +
  `Explicitly note that C was expected to fail (exit 1). End with a one-line overall verdict (e.g. "2/3 succeeded, C failed as intended").`,
  { label: 'summarize:D', phase: 'Summarize' }
)

return { results, summary }

